package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;

/** A transfer just made: the person as they stood on the sheet they left, the sheet they went to,
 *  that sheet's figures before they arrived, and the person there they were merged into (null: none),
 *  for its audit lines. */
public record Transfer(Person person, String to, Rollup toBefore, Person into) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the transfer just made on the sheet the person left (PERSON_TRANSFERRED ... to=). */
public class RecordPersonTransferred {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Transfer transfer, Audit audit) {
        audit.record("PERSON_TRANSFERRED sheet=" + transfer.person().getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + transfer.person().getName() + " to=" + transfer.to());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the transfer just made on the sheet the person went to (PERSON_TRANSFERRED ... from=),
 *  the merge into whoever there had their name or an alias (PERSON_MERGED), then that sheet's ROLLUP/TOTALS lines. */
public class RecordPersonArrived {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Transfer transfer, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Audit audit) {
        String user = by == null ? "" : by;
        String to = transfer.to();
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + user
                + " name=" + transfer.person().getName() + " from=" + transfer.person().getSheetId());
        if (transfer.into() != null) {
            audit.record("PERSON_MERGED sheet=" + to + " by=" + user
                    + " from=" + transfer.person().getName() + " into=" + transfer.into().getName());
        }
        Rollup after = Rollup.of(to, people, claims, rates, sheets, settings);
        for (String line : after.changesSince(transfer.toBefore(), to, user)) {
            audit.record(line);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbers;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** A steward transfers the person to another sheet: they arrive with every grade given them (and its
 *  from-date), their terms, contact and aliases, and their claims with their status, dates, notes,
 *  tags, frozen figures, the figures a statement bound them to, logs and comments; each claim that had a number gets the other sheet's next,
 *  in the order the claims were opened (by the sheet's today then, then the order they were added).
 *  Their statement count starts at 0, and references, holds and
 *  settle batches are not carried. They leave this sheet entirely: patron links (either way), pool
 *  memberships, watches and closed periods' fixed totals are dropped. When someone on the other sheet
 *  already has their name or an alias (as names are compared), they are merged into that person
 *  there, as a merge does (see MergePerson): their claims after theirs, their statement count added
 *  to theirs (theirs keeping their last statement), their name and aliases joined to theirs, the rest of them (contact included) dropped. Refused (nothing written) for anyone but a
 *  steward, a retired person, this sheet's own id or an archived sheet, when their names match more
 *  than one person there or a retired one, and (when not merged) when their contact is already there. */
public class TransferPerson {
    public void transfer(@RequestParam(name = "by", required = false) String by,
            @Val TransferRequest request, @Val Person person, PersonRepository people,
            ClaimRepository claims, PeriodRepository periods, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Transfer> transferred) throws InvalidPersonException {
        String user = by == null ? "" : by;
        String sheetId = person.getSheetId();
        String to = request.to();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new InvalidPersonException("Only a steward can transfer people");
        }
        if (to.equals(sheetId)) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet");
        }
        if (person.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be transferred");
        }
        if (sheets.isArchived(to)) {
            throw new InvalidPersonException("The sheet is archived: " + to);
        }
        Set<Long> matched = new LinkedHashSet<>();
        for (String name : names(person)) {
            Person match = people.findByName(to, name);
            if (match != null) {
                matched.add(match.getId());
            }
        }
        if (matched.size() > 1) {
            throw new InvalidPersonException("The name and aliases match more than one person on " + to);
        }
        Person into = matched.isEmpty() ? null : people.find(to, matched.iterator().next());
        if (into != null && into.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        if (into == null && person.getContact() != null && people.contactTaken(to, person.getContact(), null)) {
            throw new InvalidPersonException("The contact is already on " + to);
        }
        sheets.open(to, user);
        Rollup before = Rollup.of(to, people, claims, rates, sheets, settings);
        for (long id : claims.transferAll(sheetId, person.getId(), to)) {
            Claim claim = claims.find(to, id);
            claims.renumber(claim, ClaimNumbers.next(claim, claims, periods, settings, sheets));
        }
        people.transfer(person, to, into != null);
        if (into != null) {
            Person arrived = people.find(to, person.getId());
            arrived.setName(person.getName()); // arrived under a stand-in, as the name is taken there
            claims.moveAll(to, arrived.getId(), into.getId());
            people.merge(arrived, into, user);
        }
        transferred.set(new Transfer(person, to, before, into));
    }

    private static List<String> names(Person person) {
        List<String> names = new ArrayList<>();
        names.add(person.getName());
        names.addAll(person.getAliases());
        return names;
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the sheet to transfer to (trimmed): refused when none is named. */
public class ValidateTransfer {
    public void validate(@RequestBody TransferRequest request, Out<TransferRequest> body)
            throws InvalidPersonException {
        String to = request == null || request.to() == null ? "" : request.to().trim();
        if (to.isEmpty()) {
            throw new InvalidPersonException("No sheet to transfer to");
        }
        body.set(new TransferRequest(to));
    }
}
package net.officefloor.hq.app.person;

/** Body of a transfer: the id of the sheet the person is transferred to. */
public record TransferRequest(String to) {
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** First write step: the sheet's figures before the change, for {@link RecordRollup}. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Out<Rollup> before) {
        before.set(Rollup.of(sheetId.trim(), people, claims, rates, sheets, settings));
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** After the change's own audit lines: a ROLLUP line per person whose figures moved, then TOTALS
 *  when a sheet total moved; nothing when no figure moved. */
public class RecordRollup {
    public void record(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, @Val Rollup before,
            PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Audit audit) {
        String id = sheetId.trim();
        Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
        for (String line : after.changesSince(before, id, by == null ? "" : by)) {
            audit.record(line);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<Person> response) {
        response.send(person);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The first step of every change: a viewer, and any change to an archived sheet, is refused before
 *  anything is read or written. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, RoleRepository roles,
            SheetRepository sheets) throws ViewerRefusedException, SheetArchivedException {
        if (sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException("The sheet is archived");
        }
        if (Role.VIEWER.equals(roles.roleOf(sheetId.trim(), by == null ? "" : by))) {
            throw new ViewerRefusedException("A viewer may change nothing");
        }
    }
}

